public static void main(Args _args)
{
    AVACostCatFromResController controller;

    controller = new AVACostCatFromResController(classStr(AVACostCatFromResService),
                                       methodStr(AVACostCatFromResService, startOperation),
                                       SysOperationExecutionMode::Synchronous);

    controller.startOperation();
}

